fn terrane_platform_compress(format: String, data: Vec<u8>, level: terrane_int_support::Int, deterministic: bool) -> TerranePlatformResult { terrane_platform_support::compress(&format, &data, level.as_big().to_string().parse::<i128>().unwrap_or(6), deterministic) }
fn terrane_platform_decompress(format: String, data: Vec<u8>, output: terrane_int_support::Int, ratio: terrane_int_support::Int, nesting: terrane_int_support::Int, work: terrane_int_support::Int) -> TerranePlatformResult { terrane_platform_support::decompress(&format, &data, output.as_big().to_string().parse::<i128>().unwrap_or(-1), ratio.as_big().to_string().parse::<i128>().unwrap_or(-1), nesting.as_big().to_string().parse::<i128>().unwrap_or(-1), work.as_big().to_string().parse::<i128>().unwrap_or(-1)) }
